    68  unsigned char *m3dimporter_readfile(char *fn, unsigned int *size) {
    69      ai_assert(nullptr != fn);
    70      ai_assert(nullptr != size);
    71      std::string file(fn);
    72      std::unique_ptr<Assimp::IOStream> pStream(
    73              (reinterpret_cast<Assimp::IOSystem *>(m3dimporter_pIOHandler))->Open(file, "rb"));
    74      size_t fileSize = 0;
    75      unsigned char *data = nullptr;
    76      // sometimes pStream is nullptr in a single-threaded scenario too for some reason
    77      // (should be an empty object returning nothing I guess)
    78      if (pStream) {
    79          fileSize = pStream->FileSize();
    80          // should be allocated with malloc(), because the library will call free() to deallocate
    81          data = (unsigned char *)malloc(fileSize);
    82          if (!data || !pStream.get() || !fileSize || fileSize != pStream->Read(data, 1, fileSize)) {
    83              pStream.reset();
    84              *size = 0;
    85              // don't throw a deadly exception, it's not fatal if we can't read an external asset
    86              return nullptr;
    87          }
    88          pStream.reset();
    89      }
    90      *size = (int)fileSize;
    91      return data;
    92  }
    93  }
