   102  M3DWrapper::M3DWrapper(IOSystem *pIOHandler, const std::vector<unsigned char> &buffer) {
   103      if (nullptr == pIOHandler) {
   104          ai_assert(nullptr != pIOHandler);
   105      }
   106
   107  #ifdef ASSIMP_USE_M3D_READFILECB
   108      // pass this IOHandler to the C callback in a thread-local pointer
   109      m3dimporter_pIOHandler = pIOHandler;
   110      m3d_ = m3d_load(const_cast<unsigned char *>(buffer.data()), m3dimporter_readfile, free, nullptr);
   111      // Clear the C callback
   112      m3dimporter_pIOHandler = nullptr;
   113  #else
   114      m3d_ = m3d_load(const_cast<unsigned char *>(buffer.data()), nullptr, nullptr, nullptr);
   115  #endif
   116  }
