   130  unsigned char *M3DWrapper::Save(int quality, int flags, unsigned int &size) {
   131  #if (!(ASSIMP_BUILD_NO_EXPORT || ASSIMP_BUILD_NO_M3D_EXPORTER))
   132      ClearSave();
   133      saved_output_ = m3d_save(m3d_, quality, flags, &size);
   134      return saved_output_;
   135  #else
   136      (void)quality;
   137      (void)flags;
   138      (void)size;
   139      return nullptr;
   140  #endif
   141  }
